IList<Student> studentList = new List<Student>() {
    new Student() { StudentID = 1, StudentName = "John", Age = 18 },
    new Student() { StudentID = 2, StudentName = "Steve", Age = 15 },
    new Student() { StudentID = 3, StudentName = "Bill", Age = 25 },
    new Student() { StudentID = 4, StudentName = "Ram", Age = 20 },
    new Student() { StudentID = 5, StudentName = "Ron", Age = 19 },
    new Student() { StudentID = 6, StudentName = "Ram", Age = 18 }
};

// Sort by name, then by age (ascending)
var thenByResult = studentList.OrderBy(s => s.StudentName)
                              .ThenBy(s => s.Age);

// Result:
// Bill, 25
// John, 18
// Ram, 18
// Ram, 20
// Ron, 19
// Steve, 15

// Sort by name, then by age (descending)
var thenByDescResult = studentList.OrderBy(s => s.StudentName)
                                   .ThenByDescending(s => s.Age);

// Result:
// Bill, 25
// John, 18
// Ram, 20  <- Note: 20 comes before 18
// Ram, 18
// Ron, 19
// Steve, 15

// Sort by name, then by age descending, then by ID
var result = studentList.OrderBy(s => s.StudentName)
                        .ThenByDescending(s => s.Age)
                        .ThenBy(s => s.StudentID);
